function adminCloudApi(){return globalThis.CampusLoopAdminCloud||null}
function adminCloudErrorMessage(error){const text=String(error?.message||error?.details||error?.hint||error||"");const code=String(error?.code||"");const map={insufficient_role:"当前云端账号没有管理员权限",stale_version:"数据已被其他管理员更新，请刷新后重试",reason_too_short:"请填写至少 5 个字的原因",document_scan_not_passed:"证件安全扫描尚未通过",listing_media_scan_not_passed:"商品图片安全扫描尚未通过",selection_state_invalid:"匹配状态已变化，请刷新后重试",quote_currency_mismatch:"报价币种与需求所在地不一致",file_scan_not_passed:"文件安全扫描尚未通过",admin_target_requires_super_admin:"只有主管理员可以处理管理员账户",cannot_ban_self:"不能封禁当前登录账号",account_already_banned:"该账户已经被封禁",active_restriction_not_found:"该账户没有有效封禁"};return map[code]||map[text.toLowerCase()]||text||"云端操作失败，请刷新后重试"}
function setAdminCloudStatus(state,message){const live=document.querySelector(".admin-live");if(!live)return;live.classList.toggle("degraded",state!=="ready");live.innerHTML=`<i></i>${adminSafeText(message)}`}
function applyAdminCloudSnapshot(snapshot){
  if(!snapshot||typeof snapshot!=="object")return;
  adminCloudSnapshot=snapshot;
  adminCloudTutorRequests=Array.isArray(snapshot.tutorRequests)?snapshot.tutorRequests:null;
  if(Array.isArray(snapshot.identityApplicants))identityApplicants.splice(0,identityApplicants.length,...snapshot.identityApplicants);
  if(Array.isArray(snapshot.marketOrders))marketOrders.splice(0,marketOrders.length,...snapshot.marketOrders);
  if(Array.isArray(snapshot.reviewFiles))reviewFiles.splice(0,reviewFiles.length,...snapshot.reviewFiles);
  if(Array.isArray(snapshot.reportCases))reportCases.splice(0,reportCases.length,...snapshot.reportCases);
  if(Array.isArray(snapshot.publishedItems)){
    // Keep cloud listings in memory. Do not persist private admin metadata or
    // document previews in localStorage.
    adminCloudSnapshot.publishedItems=snapshot.publishedItems;
  }
  if(adminInitialized){
    renderUserManagement();renderIdentityTable();renderPublishedItems();renderMarketOrders();renderTutorRequestQueue();renderTutorApproval();renderFileReviewTable();renderReportTable();
  }
}
async function refreshAdminCloud(){
  const api=adminCloudApi();
  if(!api||!adminCloudActive)return null;
  try{const snapshot=await api.refresh();applyAdminCloudSnapshot(snapshot);setAdminCloudStatus("ready","云端已连接");return snapshot}
  catch(error){console.error("CampusLoop admin cloud refresh failed",error);setAdminCloudStatus("degraded","云端读取失败");showAdminToast(adminCloudErrorMessage(error),"cloud-off");return null}
}
async function initializeAdminCloud(){
  if(adminCloudInitPromise)return adminCloudInitPromise;
  adminCloudInitPromise=(async()=>{
    const api=adminCloudApi();
    if(!api||!api.configured){setAdminCloudStatus("local","本地演示数据");return}
    try{
      const info=await api.init();
      if(info.mode!=="v2"){setAdminCloudStatus("local",info.mode==="legacy"?"兼容数据模式":"本地演示数据");return}
      if(!info.authorized){setAdminCloudStatus("local","等待云端管理员会话");return}
      adminCloudActive=true;
      const snapshot=await api.refresh();
      applyAdminCloudSnapshot(snapshot);
      adminCloudUnsubscribe=api.subscribe(()=>{window.clearTimeout(adminCloudRefreshTimer);adminCloudRefreshTimer=window.setTimeout(()=>refreshAdminCloud(),250)});
      setAdminCloudStatus("ready",`云端已连接 · ${info.role==="super_admin"?"主管理员":"运营管理员"}`);
    }catch(error){console.error("CampusLoop admin cloud initialization failed",error);setAdminCloudStatus("degraded","云端不可用，使用本地数据")}
  })();
  return adminCloudInitPromise;
}
async function runAdminCloudAction(method,args,fallback){
  const api=adminCloudApi();
  if(!adminCloudActive||!api||typeof api[method]!=="function")return fallback();
  try{await api[method](args);await refreshAdminCloud();return true}
  catch(error){console.error(`CampusLoop admin cloud ${method} failed`,error);showAdminToast(adminCloudErrorMessage(error),"triangle-alert");return false}
}

function renderAdminIcons(){if(window.lucide?.createIcons)window.lucide.createIcons({attrs:{"aria-hidden":"true",focusable:"false"}})}
function adminSafeText(value){return String(value??"").replace(/[&<>"']/g,character=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[character])}
function showAdmin(view){adminPanels.forEach(panel=>panel.classList.toggle("active",panel.dataset.adminPanel===view));document.querySelectorAll("[data-admin-view]").forEach(button=>button.classList.toggle("active",button.dataset.adminView===view));document.querySelector("#adminTitle").textContent=adminTitles[view]||adminTitles.overview;history.replaceState(null,"",`#${view}`);window.scrollTo({top:0,behavior:"smooth"})}
function showAdminToast(message,icon="check-circle-2"){let region=document.querySelector("#adminToastRegion");if(!region){region=document.createElement("div");region.id="adminToastRegion";region.className="admin-toast-region";document.body.append(region)}const toast=document.createElement("div");toast.className="admin-toast";toast.innerHTML=`<i data-lucide="${icon}"></i><span>${adminSafeText(message)}</span>`;region.append(toast);renderAdminIcons();window.setTimeout(()=>toast.remove(),3200)}

async function adminSha256(value){if(!globalThis.crypto?.subtle)throw new Error("secure_hash_unavailable");const bytes=new TextEncoder().encode(value),digest=await globalThis.crypto.subtle.digest("SHA-256",bytes);return [...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,"0")).join("")}
function validAdminSession(value){if(!value||typeof value!=="object"||!value.id||!value.username||!value.role||!adminRoles[value.role])return false;const account=adminAccounts[value.username];if(!account)return false;const allowedRoles=Array.isArray(value.allowedRoles)&&value.allowedRoles.length?value.allowedRoles:account.allowedRoles;if(!allowedRoles.includes(value.role))return false;if(!value.cloud&&account.id!==value.id)return false;if(value.cloud&&!value.cloudUserId)return false;const issuedAt=Date.parse(value.issuedAt||"");return Boolean(issuedAt&&Date.now()-issuedAt<adminSessionMaxAgeMs)}
function readAdminSession(){try{const value=JSON.parse(sessionStorage.getItem(adminSessionStorageKey)||"null");if(!validAdminSession(value))return null;const account=adminAccounts[value.username];return {...value,role:account.role,allowedRoles:[...account.allowedRoles]}}catch{return null}}
function saveAdminSession(value){adminSession=value;try{sessionStorage.setItem(adminSessionStorageKey,JSON.stringify(value))}catch{}return value}
function clearAdminSession(){const wasCloud=Boolean(adminSession?.cloud);adminSession=null;try{sessionStorage.removeItem(adminSessionStorageKey)}catch{}if(wasCloud)Promise.resolve(adminCloudApi()?.signOut?.()).catch(error=>console.warn("CampusLoop admin cloud sign out failed",error));if(adminCloudUnsubscribe){adminCloudUnsubscribe();adminCloudUnsubscribe=null}adminCloudActive=false;adminCloudSnapshot=null;adminCloudInitPromise=null;document.body.classList.remove("admin-authenticated");const shell=document.querySelector("#adminShell"),gate=document.querySelector("#adminAuthGate");if(shell)shell.hidden=true;if(gate)gate.hidden=false}
function getAdminRole(){return adminSession?.role&&adminRoles[adminSession.role]?adminSession.role:"operations"}
async function authenticateAdmin(username,password){const identifier=String(username||"").trim(),localAccount=adminAccounts[identifier],cloud=adminCloudApi();if(cloud?.configured){let cloudInfo=null;try{cloudInfo=await cloud.init()}catch(error){if(cloud.mode==="v2")throw error}if(cloudInfo?.mode==="v2"){if(!localAccount)return null;try{const result=await cloud.signIn({identifier,password});const cloudRole=result.role==="super_admin"?"super":"operations";return {...localAccount,role:cloudRole,allowedRoles:cloudRole==="super"?["super","operations"]:["operations"],cloud:true,cloudUserId:result.user?.id||""}}catch(error){if(["cloud_identifier_requires_email","cloud_schema_unavailable"].includes(error?.code))return null;throw error}}}if(!localAccount){await adminSha256(`unknown:${password}`);return null}const digest=await adminSha256(`${localAccount.salt}:${password}`);if(digest!==localAccount.passwordHash)return null;return localAccount}
function setAdminAuthMessage(message,type=""){const element=document.querySelector("#adminAuthMessage");if(!element)return;element.textContent=message;element.className=`admin-auth-message${type?` ${type}`:""}`}
function showAdminGate(){const shell=document.querySelector("#adminShell"),gate=document.querySelector("#adminAuthGate");if(shell)shell.hidden=true;if(gate)gate.hidden=false;document.body.classList.remove("admin-authenticated");window.setTimeout(()=>document.querySelector("#adminAuthUsername")?.focus(),0);renderAdminIcons()}
function grantAdminAccess(account,role=account.role){const allowedRoles=Array.isArray(account.allowedRoles)&&account.allowedRoles.length?account.allowedRoles:[account.role];const selectedRole=allowedRoles.includes(role)?role:account.role;adminSession=saveAdminSession({version:1,id:account.id,username:account.username,role:selectedRole,allowedRoles,cloud:Boolean(account.cloud),cloudUserId:account.cloudUserId||"",issuedAt:new Date().toISOString()});const shell=document.querySelector("#adminShell"),gate=document.querySelector("#adminAuthGate");if(shell)shell.hidden=false;if(gate)gate.hidden=true;document.body.classList.add("admin-authenticated");setAdminAuthMessage("");initializeAdminApp()}
function bindAdminAuth(){const form=document.querySelector("#adminAuthForm");if(!form)return;form.addEventListener("submit",async event=>{event.preventDefault();if(adminAuthBusy)return;const username=String(new FormData(form).get("username")||"").trim(),password=String(new FormData(form).get("password")||"");if(!username||!password){setAdminAuthMessage("请输入管理员账号和密码");return}adminAuthBusy=true;const submit=document.querySelector("#adminAuthSubmit");if(submit)submit.disabled=true;setAdminAuthMessage("正在验证账号…");try{const account=await authenticateAdmin(username,password);if(!account){setAdminAuthMessage("账号或密码不正确");return}grantAdminAccess(account)}catch(error){console.error("CampusLoop admin authentication failed",error);setAdminAuthMessage("登录服务暂时不可用，请稍后重试")}finally{adminAuthBusy=false;if(submit)submit.disabled=false}});renderAdminIcons()}
function renderAdminRole(){const roleId=getAdminRole(),role=adminRoles[roleId],button=document.querySelector("#adminRoleButton"),label=document.querySelector("#adminRoleLabel"),icon=document.querySelector("#adminRoleIcon"),menu=document.querySelector("#adminRoleMenu");if(!button||!label||!icon||!menu)return;label.textContent=role.label;icon.innerHTML=`<i data-lucide="${role.icon}"></i>`;button.setAttribute("aria-label",`当前角色：${role.label}，点击切换`);const account=adminAccounts[adminSession?.username],allowedRoles=Array.isArray(adminSession?.allowedRoles)&&adminSession.allowedRoles.length?adminSession.allowedRoles:account?.allowedRoles||[];menu.querySelectorAll("[data-admin-role-option]").forEach(option=>{const optionRole=option.dataset.adminRoleOption,allowed=allowedRoles.includes(optionRole),selected=optionRole===roleId;option.hidden=!allowed;option.classList.toggle("selected",selected);option.setAttribute("aria-checked",String(selected));option.querySelector("[data-role-check]").hidden=!selected});renderUserManagement();renderAdminIcons()}
function setAdminRoleMenuOpen(open,returnFocus=false){const button=document.querySelector("#adminRoleButton"),menu=document.querySelector("#adminRoleMenu");if(!button||!menu)return;menu.hidden=!open;button.setAttribute("aria-expanded",String(open));button.classList.toggle("active",open);if(open){setAdminNotificationOpen(false);menu.querySelector('[aria-checked="true"]')?.focus({preventScroll:true})}else if(returnFocus)button.focus({preventScroll:true})}
function setupAdminRoleSwitcher(){const button=document.querySelector("#adminRoleButton");if(!button)return;const wrap=document.createElement("div");wrap.className="admin-role-switcher";button.before(wrap);wrap.append(button);wrap.insertAdjacentHTML("beforeend",'<div class="admin-role-menu" id="adminRoleMenu" role="menu" aria-label="选择管理角色" hidden><div class="admin-role-menu-head"><strong>切换管理角色</strong><small>仅显示当前账号已有权限</small></div><button class="admin-role-option" data-admin-role-option="operations" type="button" role="menuitemradio" aria-checked="true"><span class="admin-role-option-icon"><i data-lucide="shield-check"></i></span><span><strong>运营管理员</strong><small>审核订单、文件与举报</small></span><i data-role-check data-lucide="check"></i></button><button class="admin-role-option" data-admin-role-option="super" type="button" role="menuitemradio" aria-checked="false"><span class="admin-role-option-icon super"><i data-lucide="crown"></i></span><span><strong>主管理员</strong><small>全部权限与平台设置</small></span><i data-role-check data-lucide="check" hidden></i></button><div class="admin-role-menu-note"><i data-lucide="lock-keyhole"></i><span>角色权限由账号授权决定</span></div></div>');button.addEventListener("click",event=>{event.stopPropagation();setAdminRoleMenuOpen(button.getAttribute("aria-expanded")!=="true")});wrap.addEventListener("click",event=>{event.stopPropagation();const option=event.target.closest("[data-admin-role-option]");if(!option||option.hidden)return;const roleId=option.dataset.adminRoleOption,allowedRoles=adminSession?.allowedRoles||[];if(!allowedRoles.includes(roleId))return;adminSession=saveAdminSession({...adminSession,role:roleId,issuedAt:new Date().toISOString()});renderAdminRole();setAdminRoleMenuOpen(false,true);showAdminToast(`已切换为${adminRoles[roleId].label}`,adminRoles[roleId].icon)});wrap.addEventListener("keydown",event=>{const options=[...wrap.querySelectorAll("[data-admin-role-option]:not([hidden])")],active=document.activeElement;if(!options.includes(active))return;if(["Enter"," "].includes(event.key)){event.preventDefault();active.click();return}if(!["ArrowDown","ArrowUp","Home","End"].includes(event.key))return;event.preventDefault();let index=options.indexOf(active);if(event.key==="ArrowDown")index=(index+1)%options.length;if(event.key==="ArrowUp")index=(index-1+options.length)%options.length;if(event.key==="Home")index=0;if(event.key==="End")index=options.length-1;options[index].focus()});document.addEventListener("click",event=>{if(!wrap.contains(event.target))setAdminRoleMenuOpen(false)});document.addEventListener("keydown",event=>{if(event.key==="Escape"&&button.getAttribute("aria-expanded")==="true")setAdminRoleMenuOpen(false,true)});document.querySelector("#adminNotificationButton")?.addEventListener("click",()=>setAdminRoleMenuOpen(false),true);renderAdminRole()}

function getUserDirectory(){try{const value=JSON.parse(localStorage.getItem(userDirectoryStorageKey));return Array.isArray(value)?value.filter(user=>user&&user.id&&user.name):[]}catch{return []}}
function managedUsers(){if(adminCloudActive&&Array.isArray(adminCloudSnapshot?.users))return adminCloudSnapshot.users.slice().sort((left,right)=>String(right.lastActiveAt||right.joinedAt||"").localeCompare(String(left.lastActiveAt||left.joinedAt||"")));const users=new Map(baseUserAccounts.map(user=>[user.id,{...user}]));getUserDirectory().forEach(user=>users.set(user.id,{...(users.get(user.id)||{}),...user,role:user.role||"普通用户"}));return [...users.values()].sort((left,right)=>String(right.lastActiveAt||right.joinedAt||"").localeCompare(String(left.lastActiveAt||left.joinedAt||"")))}
function getAccountRestrictions(){if(adminCloudActive&&adminCloudSnapshot?.restrictions)return adminCloudSnapshot.restrictions;try{const value=JSON.parse(localStorage.getItem(accountRestrictionStorageKey));return value&&typeof value==="object"&&!Array.isArray(value)?value:{}}catch{return {}}}
function accountRestrictionState(userId){const restriction=getAccountRestrictions()[userId];if(!restriction||restriction.status!=="banned")return "active";if(restriction.expiresAt&&Date.parse(restriction.expiresAt)<=Date.now())return "expired";return "banned"}
function formatAdminDate(value,includeTime=true){const date=new Date(value);if(Number.isNaN(date.getTime()))return "未记录";return date.toLocaleString("zh-CN",includeTime?{year:"numeric",month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"}:{year:"numeric",month:"short",day:"numeric"})}
function restrictionEndLabel(restriction,state=restriction?.userId?accountRestrictionState(restriction.userId):"active"){if(!restriction)return "-";if(state==="expired")return `已于 ${formatAdminDate(restriction.expiresAt)} 到期`;if(restriction.status!=="banned")return "已解除";return restriction.expiresAt?`至 ${formatAdminDate(restriction.expiresAt)}`:"永久"}
function userStatusMeta(userId){const state=accountRestrictionState(userId);return state==="banned"?{label:"已封禁",className:"danger"}:state==="expired"?{label:"已到期",className:"neutral"}:{label:"正常",className:"success"}}
function currentManagedUser(){const layer=document.querySelector("#userManagementLayer");return managedUsers().find(user=>user.id===layer?.dataset.userId)||null}

function setupUserManagement(){
  const surface=document.querySelector("#userManagementSurface");
  if(!surface)return;
  surface.innerHTML=`<div class="user-permission-banner" id="userPermissionBanner"></div><div class="table-tools full-tools user-management-tools"><label><i data-lucide="search"></i><input id="userSearch" type="search" autocomplete="off" placeholder="搜索姓名、邮箱或用户编号" aria-label="搜索用户"></label><select id="userStatusFilter" aria-label="按账户状态筛选"><option value="all">全部状态</option><option value="active">正常</option><option value="banned">已封禁</option><option value="expired">已到期</option></select></div><div class="data-table-wrap"><table class="user-management-table"><thead><tr><th>用户</th><th>角色</th><th>所在地区</th><th>最近活跃</th><th>账户状态</th><th>限制期限</th><th>操作</th></tr></thead><tbody id="userManagementBody"></tbody></table></div>`;
  document.body.insertAdjacentHTML("beforeend",'<div class="identity-review-layer" id="userManagementLayer" hidden><button class="identity-drawer-backdrop" data-close-user-drawer type="button" aria-label="关闭用户详情"></button><aside class="identity-review-drawer user-management-drawer" id="userManagementDrawer" role="dialog" aria-modal="true" aria-label="用户账户管理"></aside></div>');
  surface.querySelector("#userSearch").addEventListener("input",renderUserManagement);
  surface.querySelector("#userStatusFilter").addEventListener("change",renderUserManagement);
  renderUserManagement();
}

function renderUserManagement(){
  const body=document.querySelector("#userManagementBody"),banner=document.querySelector("#userPermissionBanner");
  if(!body||!banner)return;
  const search=String(document.querySelector("#userSearch")?.value||"").trim().toLowerCase(),filter=document.querySelector("#userStatusFilter")?.value||"all",role=getAdminRole(),users=managedUsers(),restrictions=getAccountRestrictions(),restrictedCount=users.filter(user=>accountRestrictionState(user.id)==="banned").length,filtered=users.filter(user=>{const status=accountRestrictionState(user.id),haystack=[user.id,user.name,user.contact,user.location].join(" ").toLowerCase();return (!search||haystack.includes(search))&&(filter==="all"||filter===status)});
  const count=document.querySelector("#restrictedUserCount");
  if(count)count.textContent=`${restrictedCount} 个受限账户`;
  banner.className=`user-permission-banner ${role==="super"?"can-manage":"read-only"}`;
  banner.innerHTML=role==="super"?'<i data-lucide="shield-check"></i><span><strong>主管理员权限</strong><small>可以封禁和解除封禁；每次操作都会记录原因、期限和操作人。</small></span>':'<i data-lucide="lock-keyhole"></i><span><strong>当前为只读权限</strong><small>运营管理员可以查看账户状态，封禁与解封仅限主管理员。</small></span>';
  body.innerHTML=filtered.length?filtered.map(user=>{const status=userStatusMeta(user.id),restriction=restrictions[user.id],state=accountRestrictionState(user.id);return `<tr><td><div class="managed-user-cell"><span>${adminSafeText(user.name.slice(0,1).toUpperCase())}</span><div><strong>${adminSafeText(user.name)}</strong><small>${adminSafeText(user.contact||user.id)}</small></div></div></td><td>${adminSafeText(user.role||"普通用户")}</td><td>${adminSafeText(user.location||"未设置")}</td><td>${adminSafeText(formatAdminDate(user.lastActiveAt||user.joinedAt,false))}</td><td><span class="status ${status.className}">${status.label}</span></td><td>${adminSafeText(restrictionEndLabel(restriction,state))}</td><td><button class="table-action ${role==="super"?"primary":""}" data-manage-user="${adminSafeText(user.id)}" type="button">${role==="super"?"管理账户":"查看"}</button></td></tr>`}).join(""):'<tr><td colspan="7"><div class="identity-table-empty"><i data-lucide="user-search"></i>没有符合条件的用户</div></td></tr>';
  const layer=document.querySelector("#userManagementLayer"),openUser=currentManagedUser();
  if(layer&&!layer.hidden&&openUser)renderUserDrawer(openUser);
  renderAdminIcons();
}

function renderRestrictionHistory(restriction){const history=Array.isArray(restriction?.history)?[...restriction.history].reverse():[];if(!history.length)return '<div class="account-history-empty">暂无账户限制记录</div>';return `<div class="account-history-list">${history.map(entry=>`<article><span class="account-history-dot ${entry.type==="ban"?"ban":"unban"}"></span><div><strong>${entry.type==="ban"?"账户已封禁":"账户已解封"}</strong><p>${adminSafeText(entry.reason||"未填写原因")}</p><small>${adminSafeText(entry.reviewer||"管理员")} · ${adminSafeText(formatAdminDate(entry.at))}${entry.type==="ban"?` · ${adminSafeText(entry.expiresAt?`至 ${formatAdminDate(entry.expiresAt)}`:"永久")}`:""}</small></div></article>`).join("")}</div>`}

function renderUserDrawer(user){
  const drawer=document.querySelector("#userManagementDrawer");
  if(!drawer||!user)return;
  const restriction=getAccountRestrictions()[user.id],state=accountRestrictionState(user.id),status=userStatusMeta(user.id),isSuper=getAdminRole()==="super",isBanned=state==="banned";
  drawer.innerHTML=`<header class="identity-drawer-head"><div><p class="admin-kicker">ACCOUNT CONTROL</p><h2>账户管理</h2><span>${adminSafeText(user.id)}</span></div><button class="admin-icon-button soft" data-close-user-drawer type="button" aria-label="关闭"><i data-lucide="x"></i></button></header><div class="identity-drawer-scroll"><div class="identity-applicant-summary"><span class="identity-avatar">${adminSafeText(user.name.slice(0,1).toUpperCase())}</span><div><strong>${adminSafeText(user.name)}</strong><small>${adminSafeText(user.contact||"未填写联系方式")}</small></div><span class="status ${status.className}">${status.label}</span></div><section class="identity-drawer-section"><div class="identity-section-title"><span>账户资料</span><small>仅用于平台管理</small></div><div class="identity-detail-grid"><div><small>用户角色</small><strong>${adminSafeText(user.role||"普通用户")}</strong></div><div><small>所在地区</small><strong>${adminSafeText(user.location||"未设置")}</strong></div><div><small>注册时间</small><strong>${adminSafeText(formatAdminDate(user.joinedAt,false))}</strong></div><div><small>最近活跃</small><strong>${adminSafeText(formatAdminDate(user.lastActiveAt||user.joinedAt,false))}</strong></div></div></section><section class="identity-drawer-section"><div class="identity-section-title"><span>当前限制</span><small>${adminSafeText(restrictionEndLabel(restriction,state))}</small></div>${isBanned?`<div class="account-restriction-card"><i data-lucide="ban"></i><div><strong>该账户当前无法登录或执行受保护操作</strong><p>${adminSafeText(restriction.reason)}</p><small>${adminSafeText(restriction.reviewer||"管理员")} · ${adminSafeText(formatAdminDate(restriction.bannedAt))}</small></div></div>`:state==="expired"?'<div class="account-access-card expired"><i data-lucide="clock-3"></i><span><strong>限制已自动到期</strong><small>用户现在可以正常登录，历史记录仍会保留。</small></span></div>':'<div class="account-access-card"><i data-lucide="circle-check"></i><span><strong>账户状态正常</strong><small>当前没有有效的登录或操作限制。</small></span></div>'}</section><section class="identity-drawer-section"><div class="identity-section-title"><span>限制记录</span><small>${Array.isArray(restriction?.history)?restriction.history.length:0} 条</small></div>${renderRestrictionHistory(restriction)}</section>${!isSuper?'<div class="account-role-warning"><i data-lucide="lock-keyhole"></i><div><strong>需要主管理员权限</strong><p>当前角色只能查看，不能封禁或解除封禁用户账户。</p></div></div>':''}<div id="accountActionPanel"></div></div><footer class="identity-drawer-actions user-drawer-actions"><button class="drawer-close-button" data-close-user-drawer type="button">关闭</button>${isSuper?`<button class="${isBanned?"drawer-approve-button":"drawer-reject-button"}" data-show-account-action="${isBanned?"unban":"ban"}" type="button"><i data-lucide="${isBanned?"shield-check":"ban"}"></i>${isBanned?"解除封禁":"封禁账户"}</button>`:""}</footer>`;
  renderAdminIcons();
}

function openUserDrawer(userId){const user=managedUsers().find(entry=>entry.id===userId),layer=document.querySelector("#userManagementLayer");if(!user||!layer)return;userDrawerReturnFocus=document.activeElement;layer.dataset.userId=user.id;renderUserDrawer(user);layer.hidden=false;document.body.classList.add("identity-drawer-open");requestAnimationFrame(()=>drawerFocusTarget()?.focus({preventScroll:true}))}
function drawerFocusTarget(){return document.querySelector("#userManagementDrawer [data-close-user-drawer]")}
function closeUserDrawer(){const layer=document.querySelector("#userManagementLayer");if(!layer||layer.hidden)return;layer.hidden=true;delete layer.dataset.userId;document.body.classList.remove("identity-drawer-open");if(userDrawerReturnFocus?.isConnected)userDrawerReturnFocus.focus({preventScroll:true});userDrawerReturnFocus=null}

function showAccountActionForm(action){
  const user=currentManagedUser(),panel=document.querySelector("#accountActionPanel");
  if(!user||!panel)return;
  if(getAdminRole()!=="super"){showAdminToast("只有主管理员可以修改账户状态","lock-keyhole");return}
  const state=accountRestrictionState(user.id);
  if((action==="ban"&&state==="banned")||(action==="unban"&&state!=="banned"))return;
  panel.innerHTML=action==="ban"?`<form class="account-action-form ban" id="accountBanForm" data-user-id="${adminSafeText(user.id)}"><div class="account-action-title"><i data-lucide="ban"></i><div><strong>封禁 ${adminSafeText(user.name)}</strong><p>提交后，该用户将立即退出并无法重新登录。</p></div></div><label>封禁期限<select name="duration" required><option value="1d">1 天</option><option value="7d" selected>7 天</option><option value="30d">30 天</option><option value="permanent">永久</option></select></label><label>封禁原因<textarea name="reason" required minlength="5" maxlength="240" rows="3" placeholder="请填写至少 5 个字的具体原因"></textarea></label><label class="account-confirm-check"><input name="confirm" value="yes" type="checkbox" required><span>我确认该操作会立即限制用户登录和受保护操作。</span></label><div><button class="table-action" data-cancel-account-action type="button">取消</button><button class="table-action reject" type="submit">确认封禁</button></div></form>`:`<form class="account-action-form unban" id="accountUnbanForm" data-user-id="${adminSafeText(user.id)}"><div class="account-action-title"><i data-lucide="shield-check"></i><div><strong>解除 ${adminSafeText(user.name)} 的封禁</strong><p>提交后，该用户可以立即重新登录并使用账户功能。</p></div></div><label>解封原因<textarea name="reason" required minlength="5" maxlength="240" rows="3" placeholder="例如：申诉审核通过，确认解除限制"></textarea></label><label class="account-confirm-check"><input name="confirm" value="yes" type="checkbox" required><span>我已核对账户信息并确认解除封禁。</span></label><div><button class="table-action" data-cancel-account-action type="button">取消</button><button class="table-action approve" type="submit">确认解封</button></div></form>`;
  renderAdminIcons();
  panel.querySelector("textarea")?.focus();
}

function saveAccountBan(userId,duration,reason,confirmed){
  const user=managedUsers().find(entry=>entry.id===userId),normalizedReason=String(reason||"").trim(),days={"1d":1,"7d":7,"30d":30}[duration]||null;
  if(getAdminRole()!=="super"){showAdminToast("当前角色没有封禁权限","lock-keyhole");return}
  if(!user||accountRestrictionState(userId)==="banned"){showAdminToast("该账户当前不能执行封禁操作","triangle-alert");return}
  if(normalizedReason.length<5||!confirmed){showAdminToast("请填写完整原因并确认操作","triangle-alert");return}
  if(adminCloudActive&&user.cloud){
    const endsAt=days?new Date(Date.now()+days*86400000).toISOString():null;
    runAdminCloudAction("banUser",{id:userId,reason:normalizedReason,endsAt},()=>false).then(ok=>{if(ok){closeUserDrawer();showAdminToast(`${user.name} 已被封禁${endsAt?`，有效至 ${formatAdminDate(endsAt)}`:"，期限为永久"}`,"ban")}});
    return;
  }
  const restrictions=getAccountRestrictions(),previous=restrictions[userId],at=new Date().toISOString(),expiresAt=days?new Date(Date.now()+days*86400000).toISOString():null,entry={type:"ban",reason:normalizedReason,duration,at,expiresAt,reviewer:"Olivia",reviewerRole:getAdminRole()};
  restrictions[userId]={userId,status:"banned",reason:normalizedReason,duration,bannedAt:at,expiresAt,reviewer:"Olivia",reviewerRole:getAdminRole(),history:[...(Array.isArray(previous?.history)?previous.history:[]),entry]};
  localStorage.setItem(accountRestrictionStorageKey,JSON.stringify(restrictions));
  renderUserManagement();
  showAdminToast(`${user.name} 已被封禁${expiresAt?`，有效至 ${formatAdminDate(expiresAt)}`:"，期限为永久"}`,"ban");
}

function saveAccountUnban(userId,reason,confirmed){
  const user=managedUsers().find(entry=>entry.id===userId),normalizedReason=String(reason||"").trim(),restrictions=getAccountRestrictions(),previous=restrictions[userId];
  if(getAdminRole()!=="super"){showAdminToast("当前角色没有解封权限","lock-keyhole");return}
  if(!user||accountRestrictionState(userId)!=="banned"){showAdminToast("该账户当前没有有效封禁","triangle-alert");return}
  if(normalizedReason.length<5||!confirmed){showAdminToast("请填写完整原因并确认操作","triangle-alert");return}
  if(adminCloudActive&&user.cloud){
    runAdminCloudAction("unbanUser",{id:userId,reason:normalizedReason},()=>false).then(ok=>{if(ok){closeUserDrawer();showAdminToast(`${user.name} 的账户封禁已解除`,"shield-check")}});
    return;
  }
  const at=new Date().toISOString(),entry={type:"unban",reason:normalizedReason,at,reviewer:"Olivia",reviewerRole:getAdminRole()};
  restrictions[userId]={...previous,status:"active",unbannedAt:at,unbanReason:normalizedReason,unbannedBy:"Olivia",history:[...(Array.isArray(previous?.history)?previous.history:[]),entry]};
  localStorage.setItem(accountRestrictionStorageKey,JSON.stringify(restrictions));
  renderUserManagement();
  showAdminToast(`${user.name} 的账户封禁已解除`,"shield-check");
}

function bindUserManagementEvents(){
  document.addEventListener("click",event=>{const manage=event.target.closest("[data-manage-user]");if(manage)openUserDrawer(manage.dataset.manageUser);if(event.target.closest("[data-close-user-drawer]"))closeUserDrawer();const action=event.target.closest("[data-show-account-action]");if(action)showAccountActionForm(action.dataset.showAccountAction);if(event.target.closest("[data-cancel-account-action]")){const panel=document.querySelector("#accountActionPanel");if(panel)panel.innerHTML=""}});
  document.addEventListener("submit",event=>{if(!["accountBanForm","accountUnbanForm"].includes(event.target.id))return;event.preventDefault();const data=new FormData(event.target),confirmed=data.get("confirm")==="yes";if(event.target.id==="accountBanForm")saveAccountBan(event.target.dataset.userId,String(data.get("duration")||""),data.get("reason"),confirmed);else saveAccountUnban(event.target.dataset.userId,data.get("reason"),confirmed)});
  document.addEventListener("keydown",event=>{if(event.key==="Escape")closeUserDrawer()});
  window.addEventListener("storage",event=>{if(event.key===accountRestrictionStorageKey||event.key===userDirectoryStorageKey)renderUserManagement()});
}

function getAdminNotificationReadIds(){try{const value=JSON.parse(localStorage.getItem(adminNotificationStorageKey));return Array.isArray(value)?value.filter(id=>adminNotifications.some(notification=>notification.id===id)):[]}catch{return []}}
function saveAdminNotificationReadIds(ids){localStorage.setItem(adminNotificationStorageKey,JSON.stringify([...new Set(ids)]));renderAdminNotifications()}
function renderAdminNotifications(){const panel=document.querySelector("#adminNotificationPanel"),button=document.querySelector("#adminNotificationButton"),badge=document.querySelector("#adminNotificationBadge");if(!panel||!button||!badge)return;const readIds=new Set(getAdminNotificationReadIds()),unread=adminNotifications.filter(notification=>!readIds.has(notification.id)).length;badge.textContent=unread;badge.hidden=unread===0;button.classList.toggle("has-unread",unread>0);button.setAttribute("aria-label",unread?`通知，${unread} 条未读`:"通知，全部已读");button.title=unread?`通知，${unread} 条未读`:"通知，全部已读";panel.querySelector("[data-notification-summary]").textContent=unread?`${unread} 条未读`:"全部已读";const markAll=panel.querySelector("[data-read-all-notifications]");markAll.disabled=unread===0;panel.querySelector("[data-notification-list]").innerHTML=adminNotifications.map(notification=>{const read=readIds.has(notification.id);return `<button class="admin-notification-item ${read?"read":"unread"}" data-admin-notification="${notification.id}" type="button"><span class="admin-notification-icon ${notification.tone}"><i data-lucide="${notification.icon}"></i></span><span class="admin-notification-copy"><strong>${adminSafeText(notification.title)}</strong><small>${adminSafeText(notification.detail)}</small></span><span class="admin-notification-meta"><time>${adminSafeText(notification.time)}</time>${read?'<i data-lucide="check"></i>':'<span aria-label="未读"></span>'}</span></button>`}).join("");renderAdminIcons()}
function setAdminNotificationOpen(open,returnFocus=false){const panel=document.querySelector("#adminNotificationPanel"),button=document.querySelector("#adminNotificationButton");if(!panel||!button)return;panel.hidden=!open;button.setAttribute("aria-expanded",String(open));button.classList.toggle("active",open);if(open){const readIds=new Set(getAdminNotificationReadIds()),firstUnread=adminNotifications.find(notification=>!readIds.has(notification.id));panel.querySelector(`[data-admin-notification="${firstUnread?.id||adminNotifications[0].id}"]`)?.focus({preventScroll:true})}else if(returnFocus)button.focus({preventScroll:true})}
function setupAdminNotifications(){const button=document.querySelector('.admin-topbar .admin-icon-button[title="通知"]');if(!button)return;button.id="adminNotificationButton";button.setAttribute("aria-controls","adminNotificationPanel");button.setAttribute("aria-expanded","false");button.setAttribute("aria-haspopup","dialog");const badge=button.querySelector("b");badge.id="adminNotificationBadge";badge.setAttribute("aria-live","polite");const wrap=document.createElement("div");wrap.className="admin-notification-wrap";button.before(wrap);wrap.append(button);wrap.insertAdjacentHTML("beforeend",'<aside class="admin-notification-panel" id="adminNotificationPanel" role="dialog" aria-label="管理员通知" hidden><div class="admin-notification-head"><div><strong>通知</strong><small data-notification-summary></small></div><button data-read-all-notifications type="button"><i data-lucide="check-check"></i>全部标为已读</button></div><div class="admin-notification-list" data-notification-list></div><div class="admin-notification-footer"><button data-notification-settings type="button"><i data-lucide="settings-2"></i>通知设置</button></div></aside>');button.addEventListener("click",event=>{event.stopPropagation();setAdminNotificationOpen(button.getAttribute("aria-expanded")!=="true")});wrap.addEventListener("click",event=>{event.stopPropagation();const item=event.target.closest("[data-admin-notification]");if(item){const notification=adminNotifications.find(entry=>entry.id===item.dataset.adminNotification);if(!notification)return;saveAdminNotificationReadIds([...getAdminNotificationReadIds(),notification.id]);setAdminNotificationOpen(false);showAdmin(notification.view);return}if(event.target.closest("[data-read-all-notifications]")){saveAdminNotificationReadIds(adminNotifications.map(notification=>notification.id));showAdminToast("所有通知已标为已读","check-check");return}if(event.target.closest("[data-notification-settings]")){setAdminNotificationOpen(false);showAdmin("settings")}});document.addEventListener("click",event=>{if(!wrap.contains(event.target))setAdminNotificationOpen(false)});document.addEventListener("keydown",event=>{if(event.key==="Escape"&&button.getAttribute("aria-expanded")==="true")setAdminNotificationOpen(false,true)});window.addEventListener("storage",event=>{if(event.key===adminNotificationStorageKey)renderAdminNotifications()});renderAdminNotifications()}

function readTutorStoredValue(key){try{return JSON.parse(localStorage.getItem(key))}catch{return null}}
function tutorStoredArray(value){if(Array.isArray(value))return value;if(value&&typeof value==="object"){if(Array.isArray(value.requests))return value.requests;if(Array.isArray(value.quotes))return value.quotes;return [value]}return []}
function tutorStateEntries(key){return tutorStoredArray(readTutorStoredValue(key)).filter(entry=>entry&&typeof entry==="object")}
function saveTutorClientState(key,state){const requestId=String(state?.requestId||""),updated=[state,...tutorStateEntries(key).filter(entry=>String(entry.requestId||"")!==requestId)];localStorage.setItem(key,JSON.stringify(updated));return state}
function removeTutorClientState(key,requestId){const updated=tutorStateEntries(key).filter(entry=>String(entry.requestId||"")!==String(requestId||""));if(updated.length)localStorage.setItem(key,JSON.stringify(updated));else localStorage.removeItem(key)}
function tutorCommerce(){return globalThis.CampusLoopCommerce||{}}
function normalizeTutorCurrency(value,countryCode=""){const commerce=tutorCommerce(),raw=String(value||"").trim();if(raw&&typeof commerce.normalizeCurrency==="function"){try{const normalized=commerce.normalizeCurrency(raw);if(normalized)return String(normalized).toUpperCase()}catch{}}if(raw){const normalized=raw.toUpperCase()==="RM"?"MYR":raw.toUpperCase();if(/^[A-Z]{3}$/.test(normalized))return normalized}if(countryCode&&typeof commerce.currencyForCountry==="function"){try{return String(commerce.currencyForCountry(countryCode)||"").toUpperCase()}catch{}}return ""}
function tutorCurrencySymbol(currencyCode){if(!currencyCode)return "";const commerce=tutorCommerce();if(typeof commerce.currencySymbol==="function"){try{return commerce.currencySymbol(currencyCode)||currencyCode}catch{}}return {MYR:"RM",GBP:"£",USD:"$",AUD:"A$",CAD:"C$",CNY:"¥",EUR:"€"}[currencyCode]||currencyCode}
function tutorCurrencyLabel(currencyCode){const symbol=tutorCurrencySymbol(currencyCode);return symbol&&symbol!==currencyCode?`${currencyCode} · ${symbol}`:currencyCode||"未设置"}
function tutorFormatMoney(amount,currencyCode){const numeric=Number(amount),commerce=tutorCommerce();if(Number.isFinite(numeric)&&currencyCode&&typeof commerce.formatMoney==="function"){try{return commerce.formatMoney(numeric,currencyCode)}catch{}}return Number.isFinite(numeric)?`${tutorCurrencySymbol(currencyCode)} ${numeric.toLocaleString()}`:"金额待确认"}
function tutorCountryName(countryCode){const commerce=tutorCommerce();if(countryCode&&typeof commerce.countryName==="function"){try{return commerce.countryName(countryCode)||countryCode}catch{}}return countryCode||"未设置国家"}
function readQuote(){return tutorStoredArray(readTutorStoredValue(tutorStorage.quote))[0]||null}
function quotePrice(quote,currencyCode=""){if(!quote)return "尚无报价";const normalizedCurrency=normalizeTutorCurrency(currencyCode||quote.currencyCode||quote.currency),billing=quote.billing||"一次性";return `${tutorFormatMoney(quote.amount,normalizedCurrency)} / ${billing}`}

function getIdentityReviews(){try{const value=JSON.parse(localStorage.getItem(identityReviewStorageKey));return value&&typeof value==="object"?value:{}}catch{return {}}}
function identityStoredApplications(){try{const value=JSON.parse(localStorage.getItem(identityApplicationStorageKey)),entries=Array.isArray(value)?value:Array.isArray(value?.applications)?value.applications:[];return entries.filter(entry=>entry&&typeof entry==="object")}catch{return []}}
function identitySubmittedLabel(value){const date=new Date(value);return Number.isNaN(date.getTime())?"刚刚提交":date.toLocaleString("zh-CN",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})}
function identityFileSizeLabel(value){const bytes=Number(value);if(!Number.isFinite(bytes)||bytes<0)return String(value||"未知大小");if(bytes<1024)return `${bytes} B`;if(bytes<1024*1024)return `${(bytes/1024).toFixed(bytes>=10240?0:1)} KB`;return `${(bytes/1024/1024).toFixed(1)} MB`}
function normalizeIdentityApplication(entry){const id=String(entry.id||"").trim();if(!id)return null;return {id,userId:String(entry.userId||""),name:String(entry.name||"未填写姓名"),email:String(entry.email||"本地账号"),docType:String(entry.docType||"身份证明"),submitted:identitySubmittedLabel(entry.submittedAt),submittedAt:String(entry.submittedAt||""),risk:String(entry.risk||"待人工核验"),nationality:String(entry.nationality||entry.countryName||entry.countryCode||entry.country||"未提供"),countryCode:String(entry.countryCode||entry.country||""),birthDate:"未提供",documentNumber:"已加密",fileName:String(entry.fileName||"未命名文件"),mimeType:String(entry.mimeType||""),fileSize:entry.fileSize,previewDataUrl:String(entry.previewDataUrl||""),source:"submitted"}}
function getIdentityApplicants(){const seen=new Set(),submitted=identityStoredApplications().map(normalizeIdentityApplication).filter(Boolean).sort((left,right)=>new Date(right.submittedAt||0)-new Date(left.submittedAt||0)).filter(applicant=>{if(seen.has(applicant.id))return false;seen.add(applicant.id);return true});return [...submitted,...identityApplicants.filter(applicant=>!seen.has(applicant.id))]}
function identityStatus(applicant){return getIdentityReviews()[applicant.id]?.status||({pending_review:"pending",approved:"approved",rejected:"rejected"}[applicant.cloudStatus]||applicant.cloudStatus)||"pending"}
function statusMeta(status){return {pending:{label:"待审核",className:"warning"},approved:{label:"已通过",className:"success"},rejected:{label:"已驳回",className:"danger"}}[status]||{label:"待审核",className:"warning"}}
function filteredIdentityApplicants(){const panel=document.querySelector('[data-admin-panel="identity"]'),query=panel.querySelector("#identitySearch")?.value.trim().toLowerCase()||"",filter=panel.querySelector("#identityStatusFilter")?.value||"all";return getIdentityApplicants().filter(applicant=>{const status=identityStatus(applicant),matchesQuery=!query||`${applicant.name} ${applicant.email} ${applicant.id} ${applicant.fileName||""} ${applicant.nationality||""}`.toLowerCase().includes(query);return matchesQuery&&(filter==="all"||filter===status)})}
function updateIdentityCounters(){const pending=getIdentityApplicants().filter(applicant=>identityStatus(applicant)==="pending").length,panel=document.querySelector('[data-admin-panel="identity"]');panel.querySelector(".queue-count").textContent=`${pending} 个待处理`;const navBadge=document.querySelector('[data-admin-view="identity"] em');if(navBadge){navBadge.textContent=pending;navBadge.hidden=pending===0}const overviewStat=document.querySelector('[data-admin-panel="overview"] .admin-stat-grid article:first-child strong');if(overviewStat)overviewStat.textContent=String(pending).padStart(2,"0");const attention=document.querySelectorAll('[data-admin-panel="overview"] .attention-row')[0]?.querySelector("strong");if(attention)attention.textContent=`${pending} 个实名认证申请`}
function renderIdentityTable(){const panel=document.querySelector('[data-admin-panel="identity"]'),tbody=panel.querySelector("tbody"),applicants=filteredIdentityApplicants();tbody.innerHTML=applicants.length?applicants.map(applicant=>{const status=identityStatus(applicant),meta=statusMeta(status);return `<tr><td><strong>${adminSafeText(applicant.name)}</strong><small>${adminSafeText(applicant.email)}</small></td><td>${adminSafeText(applicant.docType)}</td><td>${adminSafeText(applicant.submitted)}</td><td><span class="${applicant.risk==="无"?"risk-low":"risk-medium"}">${adminSafeText(applicant.risk)}</span></td><td><span class="status ${meta.className}">${meta.label}</span></td><td><button class="table-action primary" data-review-identity="${adminSafeText(applicant.id)}" type="button">${status==="pending"?"审核资料":"查看结果"}</button></td></tr>`}).join(""):'<tr><td colspan="6"><div class="identity-table-empty"><i data-lucide="search-x"></i><span>没有符合条件的申请</span></div></td></tr>';updateIdentityCounters();renderAdminIcons()}
function identityDocumentPreview(applicant){if(applicant.source==="submitted"){const imageData=/^data:image\/(?:png|jpeg|webp);base64,/i.test(applicant.previewDataUrl)?applicant.previewDataUrl:"",isPdf=applicant.mimeType.toLowerCase()==="application/pdf"||/\.pdf$/i.test(applicant.fileName),fileSize=identityFileSizeLabel(applicant.fileSize);return `<div class="document-preview identity-uploaded-preview"><div class="document-preview-top"><span class="document-mark">${isPdf?"PDF":"IMG"}</span><span><strong>${adminSafeText(applicant.fileName)}</strong><small>${adminSafeText(fileSize)} · 仅管理员可见</small></span><i data-lucide="lock-keyhole"></i></div>${imageData?`<figure class="identity-uploaded-image"><img src="${adminSafeText(imageData)}" alt="${adminSafeText(applicant.docType)}上传预览"><figcaption><i data-lucide="scan-eye"></i>请人工核对姓名、清晰度和证件有效性</figcaption></figure>`:`<div class="identity-uploaded-file"><span><i data-lucide="${isPdf?"file-text":"image-off"}"></i></span><div><strong>${isPdf?"PDF 证件文件":"图片预览不可用"}</strong><small>${isPdf?"浏览器中不展示 PDF 原件，请依据文件信息完成审核。":"文件元数据已收到，可驳回并请用户重新上传。"}</small></div></div>`}</div>`}return `<div class="document-preview"><div class="document-preview-top"><span class="document-mark">CL</span><span><strong>${adminSafeText(applicant.docType)}</strong><small>加密预览 · 仅用于审核</small></span><i data-lucide="lock-keyhole"></i></div><div class="document-preview-body"><span class="document-photo"><i data-lucide="user-round"></i></span><div><small>姓名</small><strong>${adminSafeText(applicant.name)}</strong><small>证件号码</small><strong>${adminSafeText(applicant.documentNumber)}</strong><small>国籍</small><strong>${adminSafeText(applicant.nationality)}</strong></div></div><span class="document-watermark">CAMPUSLOOP REVIEW</span></div>`}
function identityApplicationDetails(applicant){if(applicant.source==="submitted")return `<div class="identity-detail-grid"><div><small>证件类型</small><strong>${adminSafeText(applicant.docType)}</strong></div><div><small>提交时间</small><strong>${adminSafeText(applicant.submitted)}</strong></div><div><small>国家 / 地区</small><strong>${adminSafeText(applicant.nationality)}</strong></div><div><small>文件大小</small><strong>${adminSafeText(identityFileSizeLabel(applicant.fileSize))}</strong></div></div>`;return `<div class="identity-detail-grid"><div><small>证件类型</small><strong>${adminSafeText(applicant.docType)}</strong></div><div><small>提交时间</small><strong>${adminSafeText(applicant.submitted)}</strong></div><div><small>出生日期</small><strong>${adminSafeText(applicant.birthDate)}</strong></div><div><small>风险提示</small><strong class="${applicant.risk==="无"?"risk-low":"risk-medium"}">${adminSafeText(applicant.risk)}</strong></div></div>`}
function identityVerificationChecks(applicant){if(applicant.source==="submitted")return `<div class="identity-check-list"><span><i data-lucide="check-circle-2"></i>申请资料与文件信息已接收</span><span><i data-lucide="shield-check"></i>文件格式符合 JPEG、PNG、WebP 或 PDF 要求</span><span class="manual"><i data-lucide="scan-eye"></i>姓名、清晰度及有效期需要人工核对</span></div>`;return '<div class="identity-check-list"><span><i data-lucide="check-circle-2"></i>证件图片清晰度通过</span><span><i data-lucide="check-circle-2"></i>姓名与账号资料一致</span><span><i data-lucide="check-circle-2"></i>证件有效期正常</span></div>'}
function renderIdentityDrawer(applicant){const review=getIdentityReviews()[applicant.id],status=identityStatus(applicant),meta=statusMeta(status),drawer=document.querySelector("#identityReviewDrawer");drawer.innerHTML=`<div class="identity-drawer-head"><div><p class="admin-kicker">IDENTITY REVIEW</p><h2>${status==="pending"?"审核申请":"审核结果"}</h2><span>${adminSafeText(applicant.id)}</span></div><button class="admin-icon-button soft" data-close-identity-drawer type="button" title="关闭"><i data-lucide="x"></i></button></div><div class="identity-drawer-scroll"><section class="identity-applicant-summary"><span class="identity-avatar">${adminSafeText(applicant.name.slice(0,1))}</span><div><strong>${adminSafeText(applicant.name)}</strong><small>${adminSafeText(applicant.email)}</small></div><span class="status ${meta.className}">${meta.label}</span></section><section class="identity-drawer-section"><div class="identity-section-title"><span>证件预览</span><small>${applicant.source==="submitted"?"用户上传预览":"敏感信息已隐藏"}</small></div>${identityDocumentPreview(applicant)}</section><section class="identity-drawer-section"><div class="identity-section-title"><span>申请信息</span></div>${identityApplicationDetails(applicant)}</section><section class="identity-drawer-section"><div class="identity-section-title"><span>${applicant.source==="submitted"?"文件检查":"自动核验"}</span></div>${identityVerificationChecks(applicant)}</section>${status==="pending"?`<section class="identity-approve-confirm" id="identityApproveConfirm" hidden><strong>确认通过这份实名认证？</strong><p>通过后，该用户可以创建交易订单。</p><div><button class="table-action" data-cancel-identity-action type="button">取消</button><button class="table-action approve" data-confirm-identity-approve="${adminSafeText(applicant.id)}" type="button">确认通过</button></div></section><form class="identity-reject-form" id="identityRejectForm" data-applicant-id="${adminSafeText(applicant.id)}" hidden><label>驳回原因<textarea name="reason" required minlength="5" maxlength="180" rows="3" placeholder="说明资料需要补充或重新提交的原因"></textarea></label><div><button class="table-action" data-cancel-identity-action type="button">取消</button><button class="table-action reject" type="submit">确认驳回</button></div></form>`:`<section class="identity-review-result ${status}"><i data-lucide="${status==="approved"?"badge-check":"circle-x"}"></i><div><strong>${meta.label}</strong><small>处理人 Olivia · ${adminSafeText(review?.reviewedAt||applicant.reviewedAt||"")}</small>${review?.reason?`<p>${adminSafeText(review.reason)}</p>`:""}</div></section>`}</div><div class="identity-drawer-actions">${status==="pending"?'<button class="drawer-reject-button" data-show-identity-reject type="button"><i data-lucide="x"></i>驳回</button><button class="drawer-approve-button" data-show-identity-approve type="button"><i data-lucide="check"></i>通过审核</button>':'<button class="drawer-close-button" data-close-identity-drawer type="button">关闭</button>'}</div>`;renderAdminIcons()}
function openIdentityDrawer(id){const applicant=getIdentityApplicants().find(entry=>entry.id===id),layer=document.querySelector("#identityReviewLayer");if(!applicant||!layer)return;const wasHidden=layer.hidden;if(wasHidden)identityDrawerReturnFocus=document.activeElement;layer.dataset.applicantId=id;renderIdentityDrawer(applicant);layer.hidden=false;document.body.classList.add("identity-drawer-open");if(wasHidden)requestAnimationFrame(()=>document.querySelector("#identityReviewDrawer [data-close-identity-drawer]")?.focus({preventScroll:true}))}
function closeIdentityDrawer(){const layer=document.querySelector("#identityReviewLayer");if(!layer||layer.hidden)return;layer.hidden=true;document.body.classList.remove("identity-drawer-open");if(identityDrawerReturnFocus?.isConnected)identityDrawerReturnFocus.focus({preventScroll:true});identityDrawerReturnFocus=null}
function saveIdentityReview(id,status,reason=""){
  const applicant=getIdentityApplicants().find(entry=>entry.id===id),normalizedReason=String(reason||"").trim();
  if(!applicant||identityStatus(applicant)!=="pending"||!["approved","rejected"].includes(status))return;
  if(status==="rejected"&&normalizedReason.length<5){showAdminToast("请填写至少 5 个字的驳回原因","triangle-alert");document.querySelector("#identityRejectForm textarea")?.focus();return}
  if(adminCloudActive&&applicant.cloud){
    runAdminCloudAction("reviewIdentity",{id:applicant.id,version:applicant.version,decision:status,reason:normalizedReason},()=>false).then(ok=>{if(ok){renderIdentityTable();openIdentityDrawer(id);showAdminToast(status==="approved"?"实名认证已通过":"申请已驳回",status==="approved"?"badge-check":"circle-x")}});
    return;
  }
  const reviews=getIdentityReviews();reviews[id]={status,reason:normalizedReason,reviewer:"Olivia",reviewedAt:new Date().toLocaleString("zh-CN",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})};localStorage.setItem(identityReviewStorageKey,JSON.stringify(reviews));renderIdentityTable();openIdentityDrawer(id);showAdminToast(status==="approved"?"实名认证已通过":"申请已驳回",status==="approved"?"badge-check":"circle-x")
}
function setupIdentityReview(){const panel=document.querySelector('[data-admin-panel="identity"]'),search=panel.querySelector('.full-tools input'),filter=panel.querySelector('.full-tools select');search.id="identitySearch";filter.id="identityStatusFilter";filter.innerHTML='<option value="all">全部状态</option><option value="pending">待审核</option><option value="approved">已通过</option><option value="rejected">已驳回</option>';document.body.insertAdjacentHTML("beforeend",'<div class="identity-review-layer" id="identityReviewLayer" hidden><button class="identity-drawer-backdrop" data-close-identity-drawer type="button" aria-label="关闭审核详情"></button><aside class="identity-review-drawer" id="identityReviewDrawer" role="dialog" aria-modal="true" aria-label="实名认证审核详情"></aside></div>');search.addEventListener("input",renderIdentityTable);filter.addEventListener("change",renderIdentityTable);renderIdentityTable()}

let publishedItemDrawerReturnFocus=null;
let knownPublishedItemIds=new Set();

