function getPublishedItemReviews(){try{const value=JSON.parse(localStorage.getItem(publishedItemReviewStorageKey));return value&&typeof value==="object"&&!Array.isArray(value)?value:{}}catch{return {}}}
function publishedItemReviewStatus(item){const status=getPublishedItemReviews()[String(item.id)]?.status||item.reviewStatus;return status==="approved"||status==="rejected"?status:"pending"}
function publishedItemStatusMeta(status){return {pending:{label:"待审核",className:"warning"},approved:{label:"已通过",className:"success"},rejected:{label:"已驳回",className:"danger"}}[status]||{label:"待审核",className:"warning"}}
function publishedItemSubmittedLabel(item){const date=new Date(item.submittedAt);return Number.isNaN(date.getTime())?adminSafeText(item.age||"刚刚"):date.toLocaleString("zh-CN",{month:"short",day:"numeric",hour:"2-digit",minute:"2-digit"})}
function publishedItemPrice(item){const commerce=tutorCommerce(),countryCode=String(item?.countryCode||item?.country||"").trim().toUpperCase(),storedCurrency=normalizeTutorCurrency(item?.currencyCode||item?.currency||"MYR"),currencyCode=countryCode&&typeof commerce.currencyForCountry==="function"?commerce.currencyForCountry(countryCode):storedCurrency;return adminSafeText(tutorFormatMoney(item?.price,currencyCode))}
function filteredPublishedItems(){const panel=document.querySelector('[data-admin-panel="market"]'),query=panel.querySelector("#publishedItemSearch")?.value.trim().toLowerCase()||"",filter=panel.querySelector("#publishedItemStatusFilter")?.value||"all";return getPublishedItems().slice().sort((left,right)=>new Date(right.submittedAt||0)-new Date(left.submittedAt||0)).filter(item=>{const status=publishedItemReviewStatus(item),haystack=`${item.id} ${item.title} ${item.category} ${item.seller} ${item.city} ${item.country}`.toLowerCase();return (!query||haystack.includes(query))&&(filter==="all"||filter===status)})}
function syncPublishedItemNotifications(){for(let index=adminNotifications.length-1;index>=0;index-=1){if(String(adminNotifications[index].id).startsWith("market-item-"))adminNotifications.splice(index,1)}getPublishedItems().filter(item=>publishedItemReviewStatus(item)==="pending").slice(0,5).reverse().forEach(item=>adminNotifications.unshift({id:`market-item-${item.id}`,view:"market",icon:"package-search",tone:"coral",title:"新商品等待发布审核",detail:`${item.seller||"卖家"} 发布了“${item.title||"未命名商品"}”`,time:publishedItemSubmittedLabel(item)}));if(document.querySelector("#adminNotificationPanel"))renderAdminNotifications()}
function updateMarketCounters(){const pendingItems=getPublishedItems().filter(item=>publishedItemReviewStatus(item)==="pending").length,pendingOrders=marketOrders.filter(order=>marketOrderReviewStatus(order)==="pending").length,total=pendingItems+pendingOrders,panel=document.querySelector('[data-admin-panel="market"]'),navBadge=document.querySelector('[data-admin-view="market"] em'),queue=panel?.querySelector(".page-section-head .queue-count");if(queue)queue.textContent=`${pendingItems} 个商品待审 · ${pendingOrders} 个订单待审`;if(navBadge){navBadge.textContent=total;navBadge.hidden=total===0;navBadge.setAttribute("aria-label",`${total} 个二手市场待审核项目`)}}
