function openPublishedItemDrawer(id){const item=getPublishedItems().find(entry=>String(entry.id)===String(id)),layer=document.querySelector("#publishedItemReviewLayer");if(!item||!layer)return;publishedItemDrawerReturnFocus=document.activeElement;layer.dataset.itemId=String(id);renderPublishedItemDrawer(item);layer.hidden=false;document.body.classList.add("identity-drawer-open");requestAnimationFrame(()=>document.querySelector("#publishedItemReviewDrawer [data-close-published-item-drawer]")?.focus({preventScroll:true}))}
