function marketOrderStatusMeta(status){return {pending:{label:"待审核",className:"warning"},waitFee:{label:"待服务费",className:"neutral"},waitExchange:{label:"待交换",className:"success"},completed:{label:"已完成",className:"success"},rejected:{label:"已驳回",className:"danger"}}[status]||{label:"待审核",className:"warning"}}
function filteredMarketOrders(){const panel=document.querySelector('[data-admin-panel="market"]'),query=panel.querySelector("#marketOrderSearch")?.value.trim().toLowerCase()||"",filter=panel.querySelector("#marketOrderStatusFilter")?.value||"all";return marketOrders.filter(order=>{const status=marketOrderDisplayStatus(order),matchesQuery=!query||`${order.id} ${order.item} ${order.seller} ${order.buyer}`.toLowerCase().includes(query);return matchesQuery&&(filter==="all"||filter===status)})}
