function renderMarketOrderDrawer(order){const review=getMarketOrderReviews()[order.id],reviewStatus=review?.status||marketOrderReviewStatus(order),displayStatus=marketOrderDisplayStatus(order),meta=marketOrderStatusMeta(displayStatus),drawer=document.querySelector("#marketOrderReviewDrawer");drawer.innerHTML=`<div class="identity-drawer-head"><div><p class="admin-kicker">MARKET ORDER REVIEW</p><h2>${reviewStatus==="pending"?"审核二手订单":"订单审核结果"}</h2><span>${order.id} · ${adminSafeText(order.time)}</span></div><button class="admin-icon-button soft" data-close-market-order-drawer type="button" title="关闭"><i data-lucide="x"></i></button></div><div class="identity-drawer-scroll"><section class="market-order-summary"><span class="market-order-icon"><i data-lucide="${order.icon||"shopping-bag"}"></i></span><div><small>${adminSafeText(order.category)}</small><strong>${adminSafeText(order.item)}</strong><span>${order.currency} ${Number(order.amount||0).toFixed(2)}</span></div><span class="status ${meta.className}">${meta.label}</span></section><section class="identity-drawer-section"><div class="identity-section-title"><span>交易双方</span><small>双方均已实名</small></div><div class="market-party-list"><div><span class="market-party-avatar mint">${adminSafeText(String(order.seller||"卖").slice(0,1))}</span><span><small>卖家</small><strong>${adminSafeText(order.seller)}</strong></span><i data-lucide="badge-check"></i></div><div><span class="market-party-avatar coral">${adminSafeText(String(order.buyer||"买").slice(0,1))}</span><span><small>买家</small><strong>${adminSafeText(order.buyer)}</strong></span><i data-lucide="badge-check"></i></div></div></section><section class="identity-drawer-section"><div class="identity-section-title"><span>订单信息</span></div><div class="identity-detail-grid"><div><small>所在城市</small><strong>${adminSafeText(order.city)}</strong></div><div><small>交付方式</small><strong>${adminSafeText(order.delivery)}</strong></div><div><small>商品金额</small><strong>${order.currency} ${Number(order.amount||0).toFixed(2)}</strong></div><div><small>风险提示</small><strong class="${order.risk==="无"?"risk-low":"risk-medium"}">${adminSafeText(order.risk)}</strong></div></div></section><section class="identity-drawer-section"><div class="identity-section-title"><span>平台服务费</span><small>买卖双方各 1%</small></div><div class="market-fee-breakdown"><span><small>卖家服务费</small><strong>${order.currency} ${Number(order.sellerFee||0).toFixed(2)}</strong></span><i data-lucide="plus"></i><span><small>买家服务费</small><strong>${order.currency} ${Number(order.buyerFee||0).toFixed(2)}</strong></span><i data-lucide="equal"></i><span><small>合计</small><strong>${order.currency} ${(Number(order.sellerFee||0)+Number(order.buyerFee||0)).toFixed(2)}</strong></span></div></section><section class="identity-drawer-section"><div class="identity-section-title"><span>自动核验</span></div><div class="identity-check-list"><span><i data-lucide="check-circle-2"></i>买卖双方实名认证有效</span><span><i data-lucide="check-circle-2"></i>订单金额与商品价格一致</span><span><i data-lucide="check-circle-2"></i>商品未命中禁售规则</span></div></section>${reviewStatus==="pending"?`<section class="identity-approve-confirm" id="marketOrderApproveConfirm" hidden><strong>确认通过这笔二手订单？</strong><p>通过后，订单将进入“${marketOrderStatusMeta(order.nextStatus).label}”状态。</p><div><button class="table-action" data-cancel-market-order-action type="button">取消</button><button class="table-action approve" data-confirm-market-order-approve="${order.id}" type="button">确认通过</button></div></section><form class="identity-reject-form" id="marketOrderRejectForm" data-order-id="${order.id}" hidden><label>驳回原因<textarea name="reason" required minlength="5" maxlength="180" rows="3" placeholder="说明订单不符合审核要求的原因"></textarea></label><div><button class="table-action" data-cancel-market-order-action type="button">取消</button><button class="table-action reject" type="submit">确认驳回</button></div></form>`:`<section class="identity-review-result ${reviewStatus}"><i data-lucide="${reviewStatus==="approved"?"badge-check":"circle-x"}"></i><div><strong>${reviewStatus==="approved"?"订单审核已通过":"订单已驳回"}</strong><small>处理人 Olivia · ${adminSafeText(review?.reviewedAt||"")}</small>${review?.reason?`<p>${adminSafeText(review.reason)}</p>`:""}</div></section>`}</div><div class="identity-drawer-actions">${reviewStatus==="pending"?'<button class="drawer-reject-button" data-show-market-order-reject type="button"><i data-lucide="x"></i>驳回订单</button><button class="drawer-approve-button" data-show-market-order-approve type="button"><i data-lucide="check"></i>审核通过</button>':'<button class="drawer-close-button" data-close-market-order-drawer type="button">关闭</button>'}</div>`;renderAdminIcons()}
function openMarketOrderDrawer(id){const order=marketOrders.find(entry=>entry.id===id),layer=document.querySelector("#marketOrderReviewLayer");if(!order||!layer)return;layer.dataset.orderId=id;renderMarketOrderDrawer(order);layer.hidden=false;document.body.classList.add("identity-drawer-open")}
