  itemSurface.insertAdjacentHTML("afterend",'<section class="admin-surface table-surface market-review-surface" id="marketOrderSurface"><div class="market-review-section-head"><div><p class="admin-kicker">ORDER QUEUE</p><h3>交易订单审核</h3><small>确认交易信息、服务费与双方状态</small></div><div class="table-tools full-tools"><label><i data-lucide="search"></i><input id="marketOrderSearch" type="search" autocomplete="off" aria-label="搜索二手订单" placeholder="搜索订单、商品或用户"></label><select id="marketOrderStatusFilter" aria-label="按订单状态筛选"><option value="all">全部状态</option><option value="pending">待审核</option><option value="waitFee">待服务费</option><option value="waitExchange">待交换</option><option value="completed">已完成</option><option value="rejected">已驳回</option></select></div></div><div class="data-table-wrap"><table><thead><tr><th>订单</th><th>商品</th><th>双方</th><th>订单金额</th><th>服务费</th><th>状态</th><th>操作</th></tr></thead><tbody id="marketOrderTableBody"></tbody></table></div></section>');
  document.body.insertAdjacentHTML("beforeend",'<div class="identity-review-layer" id="publishedItemReviewLayer" hidden><button class="identity-drawer-backdrop" data-close-published-item-drawer type="button" aria-label="关闭商品审核详情"></button><aside class="identity-review-drawer published-item-drawer" id="publishedItemReviewDrawer" role="dialog" aria-modal="true" aria-label="商品发布审核详情"></aside></div><div class="identity-review-layer" id="marketOrderReviewLayer" hidden><button class="identity-drawer-backdrop" data-close-market-order-drawer type="button" aria-label="关闭订单审核详情"></button><aside class="identity-review-drawer market-order-drawer" id="marketOrderReviewDrawer" role="dialog" aria-modal="true" aria-label="二手订单审核详情"></aside></div>');
  panel.querySelector("#publishedItemSearch").addEventListener("input",renderPublishedItems);
