function reportActionMeta(action){return {confirm:{label:"确认违规",icon:"shield-check",buttonLabel:"确认并执行处理"},dismiss:{label:"驳回举报",icon:"circle-x",buttonLabel:"确认驳回"},escalate:{label:"转主管调查",icon:"user-round-search",buttonLabel:"确认转交"}}[action]}
function filteredReports(){const panel=document.querySelector('[data-admin-panel="reports"]'),query=panel.querySelector("#reportSearch")?.value.trim().toLowerCase()||"",filter=panel.querySelector("#reportStatusFilter")?.value||"all";return reportCases.filter(report=>{const status=reportStatus(report),haystack=`${report.id} ${report.typeLabel} ${report.title} ${report.related} ${report.target} ${report.summary}`.toLowerCase();return (!query||haystack.includes(query))&&(filter==="all"||filter===status)})}
function updateReportCounters(){const pending=reportCases.filter(report=>reportStatus(report)==="pending").length,investigating=reportCases.filter(report=>reportStatus(report)==="investigating").length,panel=document.querySelector('[data-admin-panel="reports"]'),navButton=document.querySelector('[data-admin-view="reports"]');const queue=panel?.querySelector(".queue-count");if(queue)queue.textContent=`${pending} 个待处理${investigating?` · ${investigating} 个调查中`:""}`;let badge=navButton?.querySelector("em");if(navButton&&!badge){badge=document.createElement("em");navButton.append(badge)}if(badge){badge.textContent=pending;badge.hidden=pending===0;badge.setAttribute("aria-label",`${pending} 个待处理案件`)}}
