function reportEvidenceMarkup(report){return `<details class="report-evidence"><summary><span><i data-lucide="paperclip"></i>查看证据摘要</span><small>${report.evidence.length} 项 · 内容已脱敏</small><i data-lucide="chevron-down" class="report-evidence-chevron"></i></summary><div class="report-evidence-list">${report.evidence.map(item=>`<article><span><i data-lucide="file-lock-2"></i></span><div><strong>${adminSafeText(item.label)}</strong><p>${adminSafeText(item.detail)}</p><small>${adminSafeText(item.meta)}</small></div></article>`).join("")}</div></details>`}
