function reportOutcome(report,action){if(action==="dismiss")return report.type==="tutoring"?"纠纷已驳回，订单保护解除，结算按原流程恢复":"举报已驳回，临时限制解除并保留审计记录";if(action==="escalate")return report.type==="tutoring"?"订单与结算已暂停并转主管调查；未自动退款":"案件已转主管调查，相关内容维持临时限制";if(report.type==="tutoring")return "服务争议确认成立；订单与结算保持暂停，由主管确定补救方案；未自动退款";if(report.type==="message")return "限制被举报账号沟通 7 天，并保留申诉入口";return "下架相关内容、警告账号并限制发布 7 天"}
