function renderReportDrawer(report){const status=reportStatus(report),statusMeta=reportStatusMeta(status),priority=reportPriorityMeta(report.priority),review=getReportReviews()[report.id],active=status==="pending"||status==="investigating",drawer=document.querySelector("#reportReviewDrawer"),typeIcon={market:"shopping-bag",tutoring:"graduation-cap",message:"message-circle"}[report.type]||"flag";drawer.innerHTML=`<div class="identity-drawer-head"><div><p class="admin-kicker">TRUST &amp; SAFETY</p><h2>${active?"案件调查详情":"案件处理结果"}</h2><span>${adminSafeText(report.id)} · ${adminSafeText(report.submitted)}</span></div><button class="admin-icon-button soft" data-close-report-drawer type="button" title="关闭" aria-label="关闭案件详情"><i data-lucide="x"></i></button></div><div class="identity-drawer-scroll"><section class="report-case-summary"><span class="report-case-icon ${report.priority}"><i data-lucide="${typeIcon}"></i></span><div><small>${adminSafeText(report.typeLabel)}</small><strong>${adminSafeText(report.title)}</strong><span>${adminSafeText(report.related)}</span></div><span class="status ${statusMeta.className}">${statusMeta.label}</span></section><section class="identity-drawer-section"><div class="identity-section-title"><span>案件信息</span><small>仅供平台审核</small></div><div class="identity-detail-grid"><div><small>关联对象</small><strong>${adminSafeText(report.related)}</strong></div><div><small>优先级</small><strong><span class="status ${priority.className}">${priority.label}优先级</span></strong></div><div><small>案件类型</small><strong>${adminSafeText(report.typeLabel)}</strong></div><div><small>提交时间</small><strong>${adminSafeText(report.submitted)}</strong></div></div></section><section class="identity-drawer-section"><div class="identity-section-title"><span>双方信息</span><small>联系方式与真实姓名已隐藏</small></div><div class="report-party-list"><div><span class="market-party-avatar mint">报</span><span><small>举报方</small><strong>${adminSafeText(report.reporter)}</strong></span><i data-lucide="lock-keyhole"></i></div><div><span class="market-party-avatar coral">被</span><span><small>被举报方</small><strong>${adminSafeText(report.target)}</strong></span><i data-lucide="lock-keyhole"></i></div></div></section><section class="identity-drawer-section"><div class="identity-section-title"><span>举报内容</span></div><div class="report-description"><i data-lucide="message-square-warning"></i><p>${adminSafeText(report.summary)}</p></div>${reportEvidenceMarkup(report)}</section><section class="identity-drawer-section"><div class="identity-section-title"><span>平台规则命中</span><small>${report.rules.length} 项</small></div><div class="report-rule-list">${report.rules.map(rule=>`<span><i data-lucide="flag"></i>${adminSafeText(rule)}</span>`).join("")}</div></section>${report.type==="tutoring"&&active?'<section class="report-safety-notice"><i data-lucide="shield-alert"></i><div><strong>纠纷保护已启用</strong><p>转主管调查会暂停订单与结算，不会自动退款。退款或恢复结算须由主管另行确认。</p></div></section>':""}<section class="identity-drawer-section"><div class="identity-section-title"><span>处理时间线</span><small>${review?.history?.length?"已记录管理员操作":"系统自动记录"}</small></div>${reportTimelineMarkup(report)}</section>${active?'<section id="reportActionPanel" hidden></section>':reportResolutionMarkup(report,status)}</div><div class="identity-drawer-actions report-drawer-actions">${status==="pending"?'<button class="drawer-reject-button" data-show-report-action="dismiss" type="button"><i data-lucide="x"></i>驳回</button><button class="drawer-escalate-button" data-show-report-action="escalate" type="button"><i data-lucide="user-round-search"></i>转主管</button><button class="drawer-violation-button" data-show-report-action="confirm" type="button"><i data-lucide="shield-check"></i>确认违规</button>':status==="investigating"?'<button class="drawer-reject-button" data-show-report-action="dismiss" type="button"><i data-lucide="x"></i>驳回举报</button><button class="drawer-violation-button" data-show-report-action="confirm" type="button"><i data-lucide="shield-check"></i>确认违规</button>':'<button class="drawer-close-button" data-close-report-drawer type="button">关闭</button>'}</div>`;renderAdminIcons()}
function openReportDrawer(id){const report=reportCases.find(entry=>entry.id===id),layer=document.querySelector("#reportReviewLayer");if(!report||!layer)return;reportDrawerReturnFocus=document.activeElement;layer.dataset.reportId=id;renderReportDrawer(report);layer.hidden=false;document.body.classList.add("identity-drawer-open");requestAnimationFrame(()=>document.querySelector("#reportReviewDrawer [data-close-report-drawer]")?.focus({preventScroll:true}))}
