    runAdminCloudAction("actOnReport",{id:report.id,version:report.version,action,reason:normalizedReason},()=>false).then(ok=>{if(ok){renderReportTable();renderReportDrawer(report);showAdminToast(action==="confirm"?"已确认违规并执行处理":action==="dismiss"?"举报已驳回":"已转主管调查",action==="dismiss"?"circle-x":action==="escalate"?"user-round-search":"shield-check")}});
    return;
